# %% pts/tests/02_storage/test_cache_integration.pct.py 2
import tempfile
import pytest

from netrun.storage.config import CacheConfig, CacheWhat, NodeCacheConfig
from netrun.storage._cache import (
    CachedEpochData,
    EffectiveCacheConfig,
    NetCacheStore,
    NodeCacheStore,
)
from netrun._iutils.hashing import HashMethod
from netrun._iutils.pickling import PicklingMethod

# %% pts/tests/02_storage/test_cache_integration.pct.py 4
def test_effective_cache_config_construction():
    """EffectiveCacheConfig can be constructed and has correct fields."""
    config = EffectiveCacheConfig(
        cache_what=CacheWhat.BOTH,
        hash_method=HashMethod.xxh64,
        pickling_method=PicklingMethod.pickle,
        pickling_args={},
        evaluate_lazy_value_for_cache=False,
        sample_size=None,
        net_version=1,
        node_version=2,
    )
    assert config.cache_what == CacheWhat.BOTH
    assert config.hash_method == HashMethod.xxh64
    assert config.pickling_method == PicklingMethod.pickle
    assert config.pickling_args == {}
    assert config.evaluate_lazy_value_for_cache is False
    assert config.sample_size is None
    assert config.net_version == 1
    assert config.node_version == 2


def test_effective_cache_config_from_net_cache_store():
    """NetCacheStore.get_effective_config returns EffectiveCacheConfig."""
    config = CacheConfig(enabled=True, include_all_nodes=True, version=5)
    store = NetCacheStore(config)
    store.register_node("A", None)

    effective = store.get_effective_config("A")
    assert isinstance(effective, EffectiveCacheConfig)
    assert effective.net_version == 5
    assert effective.node_version == 5  # defaults to net version

    store.close()


def test_effective_cache_config_node_override():
    """Node-level config overrides net-level in EffectiveCacheConfig."""
    config = CacheConfig(enabled=True, include_all_nodes=True, version=1)
    store = NetCacheStore(config)
    store.register_node("A", NodeCacheConfig(version=10, cache_what=CacheWhat.INPUT_ONLY))

    effective = store.get_effective_config("A")
    assert effective.net_version == 1
    assert effective.node_version == 10
    assert effective.cache_what == CacheWhat.INPUT_ONLY

    store.close()


def test_effective_cache_config_returns_none_without_config():
    """NetCacheStore.get_effective_config returns None when no net config."""
    store = NetCacheStore(None)
    assert store.get_effective_config("A") is None
    store.close()

# %% pts/tests/02_storage/test_cache_integration.pct.py 6
def test_reservoir_sampling_persists_epoch_count():
    """Epoch count persists across NodeCacheStore re-creation."""
    with tempfile.TemporaryDirectory() as tmpdir:
        # Create store, store 3 entries
        store1 = NodeCacheStore(cache_dir=tmpdir, sample_size=5)
        for i in range(3):
            data = CachedEpochData(
                input_salvo_hash=i,
                net_version=1,
                node_version=1,
                input_values_by_port={"x": [i]},
                output_port_values={"out": [i * 2]},
                output_salvo_names=["send"],
                consumed_input_ports={"x"},
                node_name="A",
                original_epoch_id=f"epoch_{i}",
            )
            store1.store(data)
        assert store1._epoch_count == 3
        store1.close()

        # Re-create store from same directory — epoch count should be restored
        store2 = NodeCacheStore(cache_dir=tmpdir, sample_size=5)
        assert store2._epoch_count == 3
        store2.close()

# %% pts/tests/02_storage/test_cache_integration.pct.py 8
def test_cache_version_mismatch_returns_none():
    """Lookup returns None when version doesn't match."""
    with tempfile.TemporaryDirectory() as tmpdir:
        store = NodeCacheStore(cache_dir=tmpdir)
        data = CachedEpochData(
            input_salvo_hash=42,
            net_version=1,
            node_version=1,
            input_values_by_port={"x": [1]},
            output_port_values={"out": [2]},
            output_salvo_names=["send"],
            consumed_input_ports={"x"},
            node_name="A",
            original_epoch_id="e1",
        )
        store.store(data)

        # Lookup with same version: hit
        assert store.lookup(42, 1, 1) is not None

        # Lookup with different net version: miss
        assert store.lookup(42, 2, 1) is None

        # Lookup with different node version: miss
        assert store.lookup(42, 1, 2) is None

        store.close()
